import{z as o,x as A,o as m,c as n,q as t,j as r,D as i,d as E,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"相干因子 σ","description":"","frontmatter":{"title":"相干因子 σ","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/coherence-sigma.md","filePath":"litho/coherence-sigma.md","lastUpdated":1791413859000}'),h={name:"litho/coherence-sigma.md"};function B(p,a,d,g,c,_){const e=A("Mermaid");return m(),n("div",null,[a[2]||(a[2]=t('<h1 id="相干因子-σ" tabindex="-1">相干因子 σ <a class="header-anchor" href="#相干因子-σ" aria-label="Permalink to &quot;相干因子 σ&quot;">​</a></h1><div class="epigraph"><p>部分相干不是一种气氛；$\\sigma$ 把照明光瞳的半径按投影 $\\mathrm{NA}$ 归一，成为可以写进工艺配方的填充比。</p><footer>—— 据 Hopkins 对有效光源的定义，以及 Mack, Fundamental Principles of Optical Lithography 对 $\\sigma$ 的产线用法整理</footer></div><p><a href="/litho/partial-coherence">上一课</a>已经说明：投影光刻既不是单平面波，也不是完全非相干，强度是互不相干源点各自相干成像后的叠加。缺口是把「光源有多大」收成一个相对投影孔径的无量纲数，并写清环形时要两个半径。本课专钉</p> \\[\\sigma=\\frac{\\mathrm{NA}_\\mathrm{illum}}{\\mathrm{NA}_\\mathrm{proj}}. \\]<p>四维 TCC 如何把任意光瞳图案收成双线性核，留给<a href="/litho/hopkins-tcc">下一课</a>。不要回头从瑞利公式讲分辨率：\\(\\sigma\\) 改的是通带里哪些级在干涉，不改 \\(\\mathrm{NA}/\\lambda\\) 这条截止。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课给出了部分相干的物理图像，但工艺单上不能写「比较相干」。照明孔径与投影孔径之比把 Köhler 光瞳上的填充半径变成一个数：\\(\\sigma\\to 0\\) 接近点源，\\(\\sigma\\to 1\\) 接近填满入瞳。同一套镜头、同一张掩模，\\(\\sigma\\) 一变，物面互相干宽度变，空中像对比随之变。缺口因此是定义与读法，而不是开始画偶极。</p><p>浸没改了像方 \\(n\\)，合同 \\(\\mathrm{NA}\\) 变了，同样的物理照明角对应的 \\(\\sigma\\) 会变。所以配方必须同时写 \\(\\mathrm{NA}\\) 与 \\(\\sigma\\)，只报其中一个没有意义——上一课的 margin 已经警告过，本课把它写成操作规则。</p><h3 id="σ-不是激光线宽" tabindex="-1">σ 不是激光线宽 <a class="header-anchor" href="#σ-不是激光线宽" aria-label="Permalink to &quot;σ 不是激光线宽&quot;">​</a></h3><p>时间相干由光谱宽度决定，空间相干由源的角大小决定。\\(\\sigma\\) 只管后者。把准分子的线宽拧窄，是色差课的旋钮；把照明光瞳填大，是本课的旋钮。两个量都叫「相干」，产线上必须分开写。</p><p><span class="marginnote">环形照明用 \\(\\sigma_\\mathrm{in}\\)–\\(\\sigma_\\mathrm{out}\\) 两个填充半径，仍按投影 \\(\\mathrm{NA}\\) 归一。中心遮拦不是「另一个 \\(\\sigma\\) 定义」，只是圆盘挖了洞。</span></p><p><span class="marginnote">直觉类比：把投影光瞳想成一扇圆窗，\\(\\sigma\\) 就是手电筒光斑半径占这扇窗半径的几成——\\(\\sigma=0.3\\) 是只照窗心的小光斑（接近点源、相干），\\(\\sigma=0.9\\) 是几乎铺满整扇窗的大光斑（接近非相干）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>常规圆照明：有效光源是半径 \\(\\sigma\\) 的圆盘，落在以投影光瞳为单位圆的坐标系里。每个源点对应一个入射方向，把物频谱在光瞳里平移 \\(\\sigma\\) 量级的一段。\\(\\sigma\\) 越大，平移的集合越大，越接近非相干极限的传递；\\(\\sigma\\) 越小，越接近阿贝的相干乘法。</p><p>互相干函数在物面上的相关宽度与照明角成反比，也就是与 \\(\\sigma\\cdot\\mathrm{NA}/\\lambda\\) 成反比。相关宽度与关键节距相比：宽则邻缝相干干涉，窄则近似独立发光。部分相干的工艺含义，就是把这根长度调到与目标周期同一量级。</p><h3 id="填充形状仍是-σ-家族" tabindex="-1">填充形状仍是 σ 家族 <a class="header-anchor" href="#填充形状仍是-σ-家族" aria-label="Permalink to &quot;填充形状仍是 σ 家族&quot;">​</a></h3><p>圆、环、四极，都先落在 \\(\\sigma\\) 坐标系里再谈图案。后课 TCC 的积分域就是这块有效光源。本课不优化像素化光瞳；只要求：说到「\\(\\sigma=0.8\\)」指圆填充半径，说到环带必须写内外两个数。偶极的极点位置同样用这个归一，那是 RET 课的画法。</p><p><span class="marginnote">Köhler 照明把源成像到光瞳，晶圆各点看到同一套入射角，所以 \\(\\sigma\\) 是光瞳几何量，不是掩模面上某点的本地相干时间。</span></p>',18)),(m(),r(l,null,{default:i(()=>[s(e,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20ILL%5B%22%E7%85%A7%E6%98%8E%20NA%22%5D%20--%3E%20SIG%5B%22%CF%83%20%3D%20NAill%20%2F%20NAproj%22%5D%0A%20%20PROJ%5B%22%E6%8A%95%E5%BD%B1%20NA%22%5D%20--%3E%20SIG%0A%20%20SIG%20--%3E%20FILL%5B%22%E5%9C%86%20%2F%20%E7%8E%AF%20%E5%A1%AB%E5%85%85%22%5D%0A%20%20FILL%20--%3E%20COH%5B%22%E7%89%A9%E9%9D%A2%E7%9B%B8%E5%85%B3%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20COH%20--%3E%20TCC%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ATCC%20%E7%A7%AF%E5%88%86%E5%9F%9F%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">数字实例：干式 \\(\\mathrm{NA}=0.75\\) 时取 \\(\\sigma=0.8\\)，照明角满足 \\(\\sin\\theta \\approx 0.8 \\times 0.75 = 0.6\\)。换成浸没 \\(\\mathrm{NA}=1.35\\) 而照明角不动，\\(\\sigma\\) 自动掉到约 \\(0.44\\)——所以浸没机台换镜头后必须重新填瞳，旧配方照抄会跑偏。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>源点在光瞳里离轴越远，衍射级整体平移越多。密线栅的一级能否与零级同时进瞳，取决于平移是否把一级从窗外拽回来——这是 \\(\\sigma\\) 与节距的耦合，机制上已是离轴照明的萌芽，本课只读圆填充：较大的 \\(\\sigma\\) 本身就包含一批轴外源点，密图形的调制往往优于点源，但三束干涉对离焦仍然脆。</p><p>\\(\\sigma\\) 太大，接近非相干，传递函数变成光瞳自相关，高频掉得快，孤立与密图形的折中会往另一头走。因此 \\(\\sigma\\) 不是「越大越像非相干显微镜就越好」，而是针对节距与图形类别的填充半径。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到部分相干工艺，先写 \\(\\mathrm{NA}\\) 与 \\(\\sigma\\)（环带写内外）。有效光源 \\(S(\\mathbf{f})\\) 定义在单位光瞳上，支撑半径为 \\(\\sigma\\)。下一课把 \\(S\\) 与两个错位光瞳的重叠叫做 TCC，不再解释 \\(\\sigma\\) 是什么。</p><p><span class="marginnote">常见误区：初学者容易以为「\\(\\sigma\\) 调大分辨率就升」。实际上 \\(\\sigma\\) 太大逼近非相干极限，高频传递反而掉得快、三束成像对离焦更脆；\\(\\sigma\\) 是按节距和图形类别折中的旋钮，不是单向加分项。</span></p>',7)),(m(),r(l,null,{default:i(()=>[s(e,{id:"mermaid-72",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%CF%83%20%E7%9A%84%E4%B8%A4%E7%AB%AF%22%5D%20--%3E%20SMALL%5B%22%CF%83%20%E5%B0%8F%EF%BC%9A%E6%8E%A5%E8%BF%91%E7%82%B9%E6%BA%90%22%5D%0A%20%20SIG%20--%3E%20BIG%5B%22%CF%83%20%E5%A4%A7%EF%BC%9A%E6%8E%A5%E8%BF%91%E5%A1%AB%E6%BB%A1%E5%85%89%E7%9E%B3%22%5D%0A%20%20SMALL%20--%3E%20C1%5B%22%E9%82%BB%E7%BC%9D%E5%BC%BA%E7%9B%B8%E5%B9%B2%EF%BC%9A%E5%AF%B9%E6%AF%94%E9%AB%98%22%5D%0A%20%20SMALL%20--%3E%20C2%5B%22%E4%BD%86%E9%80%9A%E9%87%8F%E5%90%83%E7%B4%A7%E3%80%81%E7%85%A7%E6%98%8E%E5%88%A9%E7%94%A8%E7%8E%87%E4%BD%8E%22%5D%0A%20%20BIG%20--%3E%20D1%5B%22%E6%8E%A5%E8%BF%91%E9%9D%9E%E7%9B%B8%E5%B9%B2%E6%9E%81%E9%99%90%EF%BC%9A%E5%85%89%E7%9E%B3%E8%87%AA%E7%9B%B8%E5%85%B3%22%5D%0A%20%20BIG%20--%3E%20D2%5B%22%E5%AF%86%E5%9B%BE%E5%BD%A2%E8%B0%83%E5%88%B6%E5%A5%BD%EF%BC%8C%E7%A6%BB%E7%84%A6%E5%8F%98%E8%84%86%22%5D%0A%20%20C1%20--%3E%20MID%5B%22%E5%B7%A5%E8%89%BA%E6%8C%89%E8%8A%82%E8%B7%9D%E4%B8%8E%E5%9B%BE%E5%BD%A2%E6%8A%98%E4%B8%AD%22%5D%0A%20%20D1%20--%3E%20MID%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(\\sigma\\) 不决定波长、不决定胶的 \\(\\gamma\\)、不包含偏振态。高 \\(\\mathrm{NA}\\) 下每个源点还要带琼斯矢量，那是矢量成像的缺口；\\(\\sigma\\) 的几何定义不变。光源形状优化把圆盘升级成二维像素，仍用同一归一坐标，不是新的相干物理。</p><p>禁止把显微镜的「时间相干长度」写进本课的 \\(\\sigma\\)。带宽效应留给色差课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\sigma=\\mathrm{NA}_\\mathrm{illum}/\\mathrm{NA}_\\mathrm{proj}\\) 是照明填充比，必须与投影 \\(\\mathrm{NA}\\) 一起报。</li><li>它描述空间相干（源的角大小），不是激光线宽。</li><li>环带用 \\(\\sigma_\\mathrm{in}\\)–\\(\\sigma_\\mathrm{out}\\)；图案再复杂也先落在这套归一里。</li><li>\\(\\sigma\\) 改物面相关宽度，从而改哪些级在干涉；截止频率仍是 \\(\\mathrm{NA}/\\lambda\\)。</li><li>下一课用这块有效光源构造 TCC。</li><li>出处：Hopkins 部分相干成像；Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',5))])}const u=o(h,[["render",B]]);export{D as __pageData,u as default};
